def dist(a,b):  # min manhattan between cell sets
    return min(abs(r1-r2)+abs(c1-c2) for r1,c1 in a for r2,c2 in b)

def is_L_path(comp):  # 1-wide path with exactly one turn
    S=set(comp); deg={}
    for r,c in comp:
        n=sum((r+dr,c+dc) in S for dr,dc in NB)
        deg[(r,c)]=n
    if max(deg.values())>2 or 0 in deg.values(): return False
    # corner = deg2 cell with both vert & horiz neighbors
    corners=[p for p,n in deg.items() if n==2 and (((p[0]-1,p[1]) in S or (p[0]+1,p[1]) in S) and ((p[0],p[1]-1) in S or (p[0],p[1]+1) in S))]
    return len(corners)==1

def dup_classes(objs):
    from collections import defaultdict
    cls=defaultdict(list)
    for col,comp in objs: cls[shape_sig(comp)].append((col,comp))
    return {k:v for k,v in cls.items() if len(v)>1}

