prog = '''NB = ((1, 0), (-1, 0), (0, 1), (0, -1))


def objects(g):
    """Return (background_color, [(color, frozenset_of_cells_of_each_component)])."""
    from collections import Counter, deque
    h, w = len(g), len(g[0])
    cnt = Counter(v for row in g for v in row)
    bg = cnt.most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if seen[r][c] or g[r][c] == bg:
                continue
            col = g[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for dr, dc in NB:
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and g[nr][nc] == col:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            comps.append((col, tuple(cells)))
    return bg, comps


def shape_sig(comp):
    rs = [p[0] for p in comp]
    cs = [p[1] for p in comp]
    return tuple(sorted((r - min(rs), c - min(cs)) for r, c in comp))


def cell_dist(a, b):
    return min(abs(r1 - r2) + abs(c1 - c2) for r1, c1 in a for r2, c2 in b)


def is_l_path(comp):
    """True if comp is a 1-wide path with exactly one turn (an L / snake)."""
    s = set(comp)
    deg = {p: sum((p[0] + dr, p[1] + dc) in s for dr, dc in NB) for p in comp}
    if max(deg.values()) > 2 or min(deg.values()) == 0:
        return False
    corners = [
        p for p, n in deg.items()
        if n == 2
        and (((p[0] - 1, p[1]) in s or (p[0] + 1, p[1]) in s)
             and ((p[0], p[1] - 1) in s or (p[0], p[1] + 1) in s))
    ]
    return len(corners) == 1


def dup_classes(objs, exclude):
    """Map shape signature -> [(color, comp), ...] keeping only duplicate shapes."""
    from collections import defaultdict
    cls = defaultdict(list)
    for col, comp in objs:
        if comp is not exclude:
            cls[shape_sig(comp)].append((col, comp))
    return {k: v for k, v in cls.items() if len(v) > 1}


def transform(grid):
    bg, objs = objects(grid)
    snakes = [comp for col, comp in objs if is_l_path(comp)]
    if not snakes:
        return [row[:] for row in grid]
    snake = max(snakes, key=len)
    snake_color = next(c for c, comp in objs if comp is snake)
    # Target: among duplicate-shape classes (ignoring color) whose members all have
    # size > 1, take each class's member farthest from the snake (ties -> larger),
    # then pick the candidate with the largest size.
    best = None
    for sig, mem in dup_classes(objs, snake).items():
        if any(len(m) < 2 for c, m in mem):
            continue
        scored = [(cell_dist(m, snake), len(m), c, m) for c, m in mem]
        b = max(scored, key=lambda t: (t[0], t[1]))
        if best is None or b[1] > best[1]:
            best = b
    if best is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r, c in best[3]:
        out[r][c] = snake_color
    return out
'''
